            rule_section(:scoring, "Warto\u015Bci kart i punktacja",
              "Atuty od najsilniejszego to walet (20 punkt\u00F3w), dziewi\u0105tka (14), as (11), dziesi\u0105tka (10), kr\u00F3l (4), dama (3), \u00F3semka i si\u00F3demka (po zero). Poza atutem kolejno\u015B\u0107 to as (11), dziesi\u0105tka (10), kr\u00F3l (4), dama (3), walet (2), dziewi\u0105tka, \u00F3semka i si\u00F3demka (po zero). Ostatnia lewa daje dodatkowe dziesi\u0119\u0107, czyli razem w rozdaniu s\u0105 162 punkty.",
              "Gdy masz kr\u00F3la i dam\u0119 atutow\u0105, zagraj dowoln\u0105 z nich przez Shift+Enter, aby zg\u0142osi\u0107 belote. Drug\u0105 zagraj tak samo, aby zg\u0142osi\u0107 rebelote. Oba zg\u0142oszenia daj\u0105 parze dwadzie\u015Bcia punkt\u00F3w, nawet przy przegranym kontrakcie. Zagranie bez zg\u0142oszenia nie daje tej premii.",
              "Para wybieraj\u0105ca atut musi zdoby\u0107 co najmniej 82 punkty i wi\u0119cej od obrony, z uwzgl\u0119dnieniem meldunku. Przy sukcesie obie strony zapisuj\u0105 zdobyte punkty. Przy pora\u017Cce obrona zapisuje wszystkie 162 punkty z lew. Przy remisie obrona zapisuje w\u0142asne punkty z lew, a punkty licytuj\u0105cych przechodz\u0105 do zwyci\u0119zcy nast\u0119pnego rozstrzygni\u0119tego rozdania. Meldunki zawsze zostaj\u0105 przy swoich parach. Wygranie wszystkich o\u015Bmiu lew daje dodatkowe dziewi\u0119\u0107dziesi\u0105t punkt\u00F3w."),
            rule_section(:coinchee, "Coinch\u00E9e i ustawienia sto\u0142u",
              "Przy tworzeniu sto\u0142u wybierz klasyczne Belote albo Coinch\u00E9e. W Coinch\u00E9e domy\u015Blnie dostajesz od razu osiem kart. Opcja pi\u0119ciu kart w\u0142\u0105cza rozdawanie w dw\u00F3ch etapach: odkryta karta trafia do zwyci\u0119zcy licytacji, a pozosta\u0142e karty rozdaje si\u0119 po niej. Odkryta karta nie ogranicza tu wyboru atutu.",
              "Oferta podaje kolor atutu i od 80 do 160 punkt\u00F3w, co dziesi\u0119\u0107. Kolejna musi zwi\u0119ksza\u0107 liczb\u0119 punkt\u00F3w. Przeciwnicy mog\u0105 da\u0107 kontr\u0119, kt\u00F3ra blokuje podbijanie i podwaja zapis. Licytuj\u0105ca para mo\u017Ce da\u0107 rekontr\u0119, zwi\u0119kszaj\u0105c mno\u017Cnik do czterech. Trzy kolejne pasy po ofercie, kontrze lub rekontrze ko\u0144cz\u0105 licytacj\u0119. Cztery pasy bez oferty powoduj\u0105 nowe rozdanie.",
              "Licytuj\u0105ca para musi osi\u0105gn\u0105\u0107 zadeklarowany pr\u00F3g i zdoby\u0107 wi\u0119cej punkt\u00F3w od obrony. Przy sukcesie ka\u017Cda strona zapisuje punkty z lew. W przeciwnym razie, tak\u017Ce przy remisie, obrona dostaje 162, a licytuj\u0105cy zero. Gra dolicza premi\u0119 za komplet lew i meldunki, a nast\u0119pnie stosuje mno\u017Cnik kontry albo rekontry do obu par."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: przegl\u0105daj karty lub pozycje menu.",
              "Enter: otw\u00F3rz wyb\u00F3r oferty podczas licytacji albo zagraj kart\u0119 podczas lewy.",
              "B: otw\u00F3rz oferty i pas dost\u0119pne w swojej turze.",
              "Shift+Enter: zagraj wskazanego kr\u00F3la lub dam\u0119 atutow\u0105 i zg\u0142o\u015B belote albo rebelote.",
              "D: odczytaj odkryt\u0105 kart\u0119, je\u015Bli jest u\u017Cywana w tym rozdaniu.",
              "F: odczytaj atut i kolor wyj\u015Bcia.",
              "R: odczytaj kontrakt.",
              "V: odczytaj kontrakt.",
              "Shift+S: odczytaj punkty rozdania przed mno\u017Cnikiem kontry.",
              "H: odczytaj swoj\u0105 r\u0119k\u0119.",
              "C: odczytaj karty na stole.",
              "Ctrl+C: przejrzyj te karty.",
              "S: odczytaj wyniki.",
              "T: sprawd\u017A, czyja jest tura.",
              "Z: znajd\u017A nast\u0119pn\u0105 kart\u0119, kt\u00F3r\u0105 mo\u017Cna zagra\u0107.",
              "Shift+Z: znajd\u017A poprzedni\u0105 kart\u0119, kt\u00F3r\u0105 mo\u017Cna zagra\u0107.",
              "Shift+C: sortuj r\u0119k\u0119 wed\u0142ug kolor\u00F3w.",
              "Shift+H: sortuj r\u0119k\u0119 wed\u0142ug warto\u015Bci.",
              "Shift+M: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymania kart.")
          ]
        when "ru"
          [
            rule_section(:play, "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F \u0438 \u0432\u0437\u044F\u0442\u043A\u0438",
              "\u0427\u0435\u0442\u0432\u0435\u0440\u043E \u0438\u0433\u0440\u0430\u044E\u0442 \u0434\u0432\u0443\u043C\u044F \u043F\u0430\u0440\u0430\u043C\u0438; \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u044B \u0441\u0438\u0434\u044F\u0442 \u0434\u0440\u0443\u0433 \u043D\u0430\u043F\u0440\u043E\u0442\u0438\u0432 \u0434\u0440\u0443\u0433\u0430. \u0412 \u043A\u043E\u043B\u043E\u0434\u0435 32 \u043A\u0430\u0440\u0442\u044B, \u043E\u0442 \u0441\u0435\u043C\u0451\u0440\u043A\u0438 \u0434\u043E \u0442\u0443\u0437\u0430. \u041F\u0435\u0440\u0432\u044B\u0439 \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E, \u0437\u0430\u0442\u0435\u043C \u0441\u0434\u0430\u0447\u0430 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043F\u043E \u043A\u0440\u0443\u0433\u0443. \u0412 \u043A\u043E\u043D\u0446\u0435 \u0441\u0434\u0430\u0447\u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0430\u0440\u0430, \u043D\u0430\u0431\u0440\u0430\u0432\u0448\u0430\u044F \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 1000 \u043E\u0447\u043A\u043E\u0432 \u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432.",
              "\u0412 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u043E\u043C \u0431\u0435\u043B\u043E\u0442\u0435 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u044F\u0442\u044C \u043A\u0430\u0440\u0442, \u0435\u0449\u0451 \u043E\u0434\u043D\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u041D\u0430\u0447\u0438\u043D\u0430\u044F \u0441 \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E\u0441\u043B\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E, \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0435\u0451 \u043C\u0430\u0441\u0442\u044C \u043A\u0430\u043A \u043A\u043E\u0437\u044B\u0440\u044C \u0438\u043B\u0438 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0442\u044C. \u041F\u043E\u0441\u043B\u0435 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043F\u0430\u0441\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u0430\u0441\u0442\u044C \u0438\u043B\u0438 \u043F\u0430\u0441. \u0412\u043E\u0441\u0435\u043C\u044C \u043F\u0430\u0441\u043E\u0432 \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0442 \u043D\u043E\u0432\u0443\u044E \u0441\u0434\u0430\u0447\u0443. \u041F\u0435\u0440\u0432\u044B\u0439 \u0432\u044B\u0431\u0440\u0430\u0432\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0430 \u0440\u0443\u043A\u0438 \u0432\u0441\u0435\u0445 \u0434\u043E\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u043A\u0430\u0440\u0442.",
              "\u041F\u0435\u0440\u0432\u044B\u043C \u0445\u043E\u0434\u0438\u0442 \u0438\u0433\u0440\u043E\u043A \u043F\u043E\u0441\u043B\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E. \u041D\u0443\u0436\u043D\u043E \u0445\u043E\u0434\u0438\u0442\u044C \u0432 \u043C\u0430\u0441\u0442\u044C. \u0415\u0441\u043B\u0438 \u0435\u0451 \u043D\u0435\u0442, \u0445\u043E\u0434\u0438\u0442\u0435 \u043A\u043E\u0437\u044B\u0440\u0435\u043C, \u043A\u0440\u043E\u043C\u0435 \u0441\u043B\u0443\u0447\u0430\u044F, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0430\u0440\u0442\u043D\u0451\u0440. \u041F\u0440\u0438 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u0445\u043E\u0434\u0435 \u043A\u043E\u0437\u044B\u0440\u0435\u043C \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u0431\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C \u0432\u043E \u0432\u0437\u044F\u0442\u043A\u0435, \u0435\u0441\u043B\u0438 \u043C\u043E\u0436\u0435\u0442\u0435. \u0411\u0435\u0437 \u043C\u0430\u0441\u0442\u0438 \u0445\u043E\u0434\u0430 \u0438 \u043A\u043E\u0437\u044B\u0440\u044F \u043C\u043E\u0436\u043D\u043E \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u0411\u0435\u0440\u0451\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C, \u0430 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u2014 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u0445\u043E\u0434\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C."),
            rule_section(:scoring, "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u0438 \u043E\u0447\u043A\u0438",
              "\u041A\u043E\u0437\u044B\u0440\u0438 \u043F\u043E \u0443\u0431\u044B\u0432\u0430\u043D\u0438\u044E: \u0432\u0430\u043B\u0435\u0442 (20 \u043E\u0447\u043A\u043E\u0432), \u0434\u0435\u0432\u044F\u0442\u043A\u0430 (14), \u0442\u0443\u0437 (11), \u0434\u0435\u0441\u044F\u0442\u043A\u0430 (10), \u043A\u043E\u0440\u043E\u043B\u044C (4), \u0434\u0430\u043C\u0430 (3), \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0430 \u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0430 (\u043F\u043E \u043D\u0443\u043B\u044E). \u0412 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u043C\u0430\u0441\u0442\u044F\u0445: \u0442\u0443\u0437 (11), \u0434\u0435\u0441\u044F\u0442\u043A\u0430 (10), \u043A\u043E\u0440\u043E\u043B\u044C (4), \u0434\u0430\u043C\u0430 (3), \u0432\u0430\u043B\u0435\u0442 (2), \u0434\u0435\u0432\u044F\u0442\u043A\u0430, \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0430 \u0438 \u0441\u0435\u043C\u0451\u0440\u043A\u0430 (\u043D\u043E\u043B\u044C). \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0434\u0435\u0441\u044F\u0442\u044C, \u0432\u0441\u0435\u0433\u043E \u0437\u0430 \u0441\u0434\u0430\u0447\u0443 \u2014 162 \u043E\u0447\u043A\u0430.",
              "\u0418\u043C\u0435\u044F \u043A\u043E\u0437\u044B\u0440\u043D\u044B\u0445 \u043A\u043E\u0440\u043E\u043B\u044F \u0438 \u0434\u0430\u043C\u0443, \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u043B\u044E\u0431\u0443\u044E \u0438\u0437 \u043D\u0438\u0445 \u0447\u0435\u0440\u0435\u0437 Shift+Enter, \u043E\u0431\u044A\u044F\u0432\u0438\u0432 \u0431\u0435\u043B\u043E\u0442, \u0437\u0430\u0442\u0435\u043C \u0434\u0440\u0443\u0433\u0443\u044E \u0442\u0430\u043A \u0436\u0435, \u043E\u0431\u044A\u044F\u0432\u0438\u0432 \u0440\u0435\u0431\u0435\u043B\u043E\u0442. \u041E\u0431\u0430 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442 \u043F\u0430\u0440\u0435 \u0434\u0432\u0430\u0434\u0446\u0430\u0442\u044C \u043E\u0447\u043A\u043E\u0432 \u0434\u0430\u0436\u0435 \u043F\u0440\u0438 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u043D\u043D\u043E\u043C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0435. \u0418\u0433\u0440\u0430 \u0431\u0435\u0437 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0431\u043E\u043D\u0443\u0441\u0430 \u043D\u0435 \u0434\u0430\u0451\u0442.",
              "\u0412\u044B\u0431\u0440\u0430\u0432\u0448\u0430\u044F \u043A\u043E\u0437\u044B\u0440\u044C \u043F\u0430\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 82 \u043E\u0447\u043A\u043E\u0432 \u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u043E\u0432 \u0441 \u0443\u0447\u0451\u0442\u043E\u043C \u0431\u0435\u043B\u043E\u0442\u0430. \u041F\u0440\u0438 \u0443\u0441\u043F\u0435\u0445\u0435 \u043E\u0431\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0432\u043E\u0438 \u043E\u0447\u043A\u0438. \u041F\u0440\u0438 \u043D\u0435\u0443\u0434\u0430\u0447\u0435 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0438 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0432\u0441\u0435 162 \u043E\u0447\u043A\u0430 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0438. \u041F\u0440\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0438 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0432\u043E\u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0438, \u0430 \u043E\u0447\u043A\u0438 \u043E\u0431\u044A\u044F\u0432\u0438\u0432\u0448\u0435\u0439 \u043F\u0430\u0440\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0440\u0435\u0448\u0430\u044E\u0449\u0435\u0439 \u0441\u0434\u0430\u0447\u0438. \u0411\u043E\u043D\u0443\u0441\u044B \u0431\u0435\u043B\u043E\u0442\u0430 \u0432\u0441\u0435\u0433\u0434\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0437\u0430 \u0441\u0432\u043E\u0438\u043C\u0438 \u043F\u0430\u0440\u0430\u043C\u0438. \u0412\u0441\u0435 \u0432\u043E\u0441\u0435\u043C\u044C \u0432\u0437\u044F\u0442\u043E\u043A \u0434\u0430\u044E\u0442 \u0434\u0435\u0432\u044F\u043D\u043E\u0441\u0442\u043E \u043E\u0447\u043A\u043E\u0432 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E."),
            rule_section(:coinchee, "\u041A\u0443\u0430\u043D\u0448 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u0442\u043E\u043B\u0430",
              "\u041F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0431\u0435\u043B\u043E\u0442 \u0438\u043B\u0438 \u043A\u0443\u0430\u043D\u0448. \u0412 \u043A\u0443\u0430\u043D\u0448\u0435 \u043E\u0431\u044B\u0447\u043D\u043E \u0441\u0440\u0430\u0437\u0443 \u0440\u0430\u0437\u0434\u0430\u044E\u0442 \u0432\u043E\u0441\u0435\u043C\u044C \u043A\u0430\u0440\u0442. \u041E\u043F\u0446\u0438\u044F \u043F\u044F\u0442\u0438 \u043A\u0430\u0440\u0442 \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0441\u0434\u0430\u0447\u0443 \u0432 \u0434\u0432\u0430 \u044D\u0442\u0430\u043F\u0430: \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0434\u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0442\u043E\u0440\u0433\u043E\u0432, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0440\u0430\u0437\u0434\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435. \u041C\u0430\u0441\u0442\u044C \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0437\u0434\u0435\u0441\u044C \u043D\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0432\u044B\u0431\u043E\u0440 \u043A\u043E\u0437\u044B\u0440\u044F.",
              "\u0417\u0430\u044F\u0432\u043A\u0430 \u0437\u0430\u0434\u0430\u0451\u0442 \u043A\u043E\u0437\u044B\u0440\u044C \u0438 \u043E\u0442 80 \u0434\u043E 160 \u043E\u0447\u043A\u043E\u0432 \u0441 \u0448\u0430\u0433\u043E\u043C \u0434\u0435\u0441\u044F\u0442\u044C. \u041D\u043E\u0432\u0430\u044F \u0437\u0430\u044F\u0432\u043A\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u0434\u0430\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0443, \u0437\u0430\u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u0432 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0438 \u0443\u0434\u0432\u043E\u0438\u0432 \u0437\u0430\u043F\u0438\u0441\u044C; \u043E\u0431\u044A\u044F\u0432\u0438\u0432\u0448\u0430\u044F \u043F\u0430\u0440\u0430 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u0439, \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432 \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u044C \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445. \u0422\u0440\u0438 \u043F\u0430\u0441\u0430 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u044F\u0432\u043A\u0438, \u043A\u043E\u043D\u0442\u0440\u044B \u0438\u043B\u0438 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u044B \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u0442\u043E\u0440\u0433\u0438. \u0427\u0435\u0442\u044B\u0440\u0435 \u043F\u0430\u0441\u0430 \u0431\u0435\u0437 \u0437\u0430\u044F\u0432\u043A\u0438 \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0442 \u043D\u043E\u0432\u0443\u044E \u0441\u0434\u0430\u0447\u0443.",
              "\u041E\u0431\u044A\u044F\u0432\u0438\u0432\u0448\u0430\u044F \u043F\u0430\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443 \u0438 \u043E\u0431\u043E\u0439\u0442\u0438 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u043E\u0432. \u041F\u0440\u0438 \u0443\u0441\u043F\u0435\u0445\u0435 \u043E\u0431\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0432\u043E\u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0438; \u0438\u043D\u0430\u0447\u0435, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043D\u0438\u0447\u044C\u044E, \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 162, \u043E\u0431\u044A\u044F\u0432\u0438\u0432\u0448\u0438\u0435 \u2014 \u043D\u043E\u043B\u044C. \u0414\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0431\u043E\u043D\u0443\u0441\u044B \u0437\u0430 \u0432\u0441\u0435 \u0432\u0437\u044F\u0442\u043A\u0438 \u0438 \u0431\u0435\u043B\u043E\u0442, \u0437\u0430\u0442\u0435\u043C \u043E\u0431\u0435\u0438\u043C \u043F\u0430\u0440\u0430\u043C \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u044C \u043A\u043E\u043D\u0442\u0440\u044B \u0438\u043B\u0438 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u044B."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438\u043B\u0438 \u043F\u0443\u043D\u043A\u0442\u044B \u043C\u0435\u043D\u044E.",
              "Enter: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443 \u043F\u0440\u0438 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0435 \u0438\u043B\u0438 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0432\u043E \u0432\u0437\u044F\u0442\u043A\u0443.",
              "B: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0432 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0437\u0430\u044F\u0432\u043A\u0438 \u0438 \u043F\u0430\u0441.",
              "Shift+Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u043D\u043E\u0433\u043E \u043A\u043E\u0440\u043E\u043B\u044F \u0438\u043B\u0438 \u0434\u0430\u043C\u0443 \u0438 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0431\u0435\u043B\u043E\u0442 \u0438\u043B\u0438 \u0440\u0435\u0431\u0435\u043B\u043E\u0442.",
              "D: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0442\u043A\u0440\u044B\u0442\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F.",
              "F: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u044C \u0438 \u043C\u0430\u0441\u0442\u044C \u0445\u043E\u0434\u0430.",
              "R: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442.",
              "V: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442.",
              "Shift+S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0447\u043A\u0438 \u0437\u0430 \u0441\u0434\u0430\u0447\u0443 \u0434\u043E \u043F\u0440\u0438\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u044F.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443.",
              "C: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043D\u0430 \u0441\u0442\u043E\u043B\u0435.",
              "Ctrl+C: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u044D\u0442\u0438 \u043A\u0430\u0440\u0442\u044B.",
              "S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0447\u0451\u0442.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0445\u043E\u0434.",
              "Z: \u043D\u0430\u0439\u0442\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "Shift+Z: \u043D\u0430\u0439\u0442\u0438 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "Shift+C: \u043E\u0442\u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0440\u0443\u043A\u0443 \u043F\u043E \u043C\u0430\u0441\u0442\u044F\u043C.",
              "Shift+H: \u043E\u0442\u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0440\u0443\u043A\u0443 \u043F\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0443.",
              "Shift+M: \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
      end
